-- submissions/insert-review
-- Records one reviewer's decision. The unique index stops a reviewer deciding the same submission twice.
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--   $2 = "0199c8a0-0000-7000-8000-00000000000a"
--   $3 = "reject"
--   $4 = "no_source"
--   $5 = "No link works"
--
-- Generated by `pnpm db:queries` from lib/db/queries/submissions.ts. Do not edit by hand.

insert into "reviews" ("id", "submission_id", "reviewer_id", "decision", "reason_code", "note", "created_at")
values (default, $1, $2, $3, $4, $5, default)
returning "id";
